// Combat and catch messages pass lowercase animal and fish names to tr().
const COVERAGE_LOWER_NAMES = [
  'Reindeer','Snow hare','Wolf','Horse','Marmot','Deer','Boar','Water buffalo','Antelope','Zebra','Warthog','Goat','Camel','Gazelle','Llama','Brown bear','Sheep','Pig','Fox',
  'Arctic char','Cod','Salmon','Pike','Perch','Sturgeon','Carp','Taimen','Grayling','Golden carp','Catfish','Koi','Ayu','Sea bream','Eel','Parrotfish','Tuna','Grouper','Rohu','Mahseer','Hilsa','Tilapia','Nile perch','Tigerfish','Mullet','Sardine','Sea bass','Octopus','Red mullet','Trout','Silverside'
];
for (const id of ['fr','es','pt','ja','zh']) {
  const lower = {};
  for (const name of COVERAGE_LOWER_NAMES) {
    const translated = L10N[id][name];
    if (translated) lower[name.toLowerCase()] = translated.charAt(0).toLocaleLowerCase(id) + translated.slice(1);
  }
  addLang(id, lower);
}
addLang('fr', {
  '<b>Walk</b>: tap a hex next to you, or any hex you have seen to travel there. Drag to look around; pinch, scroll or use the − and + buttons next to the menu to zoom (Settings: Map zoom).': '<b>Marcher</b> : touche une case voisine pour y aller, ou une case déjà vue pour voyager jusqu’à elle. Fais glisser pour regarder autour ; pince, fais défiler ou utilise les boutons − et + près du menu pour zoomer (Paramètres : zoom de la carte).',
  '<b>Bag and forge</b>: the Bag shows what you have equipped and what is spare. Keep the hides, fangs, ink essence and pearls you win: the blacksmith’s Forge turns them into stronger gear (+1 to +5) and into weapons and armour no shop sells. Every alchemist has a Brew tab: turn fish, hides, fangs and ink essence into potions.': '<b>Sac et forge</b> : le Sac montre ce que tu portes et ce qui est en réserve. Garde les peaux, crocs, essences d’encre et perles gagnés : la Forge du forgeron les transforme en équipement plus puissant (de +1 à +5), ainsi qu’en armes et armures introuvables en boutique. Chaque alchimiste a un onglet Préparer : transforme poissons, peaux, crocs et essence d’encre en potions.',
  '<b>Kingdom materials</b>: every kingdom has its own monster part (only its monsters drop it) and its own plant (when you stand where it grows, a <b>Gather</b> button appears; about 1 forest, plains or hills tile in 10). Its smiths and alchemists need them for that kingdom’s special gear and potion.': '<b>Matériaux des royaumes</b> : chaque royaume possède une partie de monstre (que seuls ses monstres lâchent) et une plante qui lui sont propres. Quand tu te tiens là où elle pousse, un bouton <b>Récolter</b> apparaît ; environ 1 case sur 10 en forêt, plaine ou colline en contient. Les forgerons et alchimistes du royaume en ont besoin pour son équipement et sa potion spéciale.',
  '<b>Fights</b>: you have 3 moves a turn. Your weapon gives your attacks; you can also block, change stance, drink a potion or use a technique.': '<b>Combats</b> : tu as 3 actions par tour. Ton arme détermine tes attaques ; tu peux aussi bloquer, changer de posture, boire une potion ou utiliser une technique.',
  '<b>The world</b>: eleven kingdoms on three continents, joined by narrow land bridges. Towns with a <b>Harbour</b> have ships to the other continents and to the Margin, the white island in the middle of the ocean.': '<b>Le monde</b> : onze royaumes répartis sur trois continents, reliés par d’étroits passages terrestres. Depuis les villes dotées d’un <b>port</b>, des navires rejoignent les autres continents et la Marge, l’île blanche au milieu de l’océan.',
  '<b>Survive</b>: eat as you travel (buy food or hunt), camp to heal, and watch the weather: snow slows you, fog hides the road, storms are dangerous.': '<b>Survivre</b> : mange en voyageant (achète de la nourriture ou chasse), campe pour te soigner et surveille la météo : la neige te ralentit, le brouillard cache la route et les tempêtes sont dangereuses.'
});
addLang('es', {
  '<b>Walk</b>: tap a hex next to you, or any hex you have seen to travel there. Drag to look around; pinch, scroll or use the − and + buttons next to the menu to zoom (Settings: Map zoom).': '<b>Caminar</b>: toca una casilla vecina para ir allí, o cualquier casilla que ya hayas visto para viajar hasta ella. Arrastra para mirar alrededor; pellizca, desplázate o usa los botones − y + junto al menú para ampliar el mapa (Ajustes: Zoom del mapa).',
  '<b>Bag and forge</b>: the Bag shows what you have equipped and what is spare. Keep the hides, fangs, ink essence and pearls you win: the blacksmith’s Forge turns them into stronger gear (+1 to +5) and into weapons and armour no shop sells. Every alchemist has a Brew tab: turn fish, hides, fangs and ink essence into potions.': '<b>Bolsa y forja</b>: la Bolsa muestra lo que llevas equipado y lo que te sobra. Guarda las pieles, colmillos, esencias de tinta y perlas que consigas: la Forja del herrero los convierte en equipo más resistente (de +1 a +5) y en armas y armaduras que no vende ninguna tienda. Cada alquimista tiene una pestaña Preparar: convierte peces, pieles, colmillos y esencia de tinta en pociones.',
  '<b>Kingdom materials</b>: every kingdom has its own monster part (only its monsters drop it) and its own plant (when you stand where it grows, a <b>Gather</b> button appears; about 1 forest, plains or hills tile in 10). Its smiths and alchemists need them for that kingdom’s special gear and potion.': '<b>Materiales de los reinos</b>: cada reino tiene una parte de monstruo (solo la sueltan sus monstruos) y una planta propias. Si te sitúas donde crece, aparecerá el botón <b>Recolectar</b>; la encontrarás en aproximadamente 1 de cada 10 casillas de bosque, llanura o colina. Los herreros y alquimistas del reino las necesitan para fabricar su equipo y poción especiales.',
  '<b>Fights</b>: you have 3 moves a turn. Your weapon gives your attacks; you can also block, change stance, drink a potion or use a technique.': '<b>Combates</b>: tienes 3 acciones por turno. Tu arma determina tus ataques; también puedes bloquear, cambiar de postura, beber una poción o usar una técnica.',
  '<b>The world</b>: eleven kingdoms on three continents, joined by narrow land bridges. Towns with a <b>Harbour</b> have ships to the other continents and to the Margin, the white island in the middle of the ocean.': '<b>El mundo</b>: once reinos repartidos en tres continentes y unidos por estrechos pasos terrestres. Desde los pueblos con <b>puerto</b> salen barcos hacia los otros continentes y el Margen, la isla blanca en medio del océano.',
  '<b>Survive</b>: eat as you travel (buy food or hunt), camp to heal, and watch the weather: snow slows you, fog hides the road, storms are dangerous.': '<b>Sobrevive</b>: come mientras viajas (compra comida o caza), acampa para curarte y vigila el tiempo: la nieve te ralentiza, la niebla oculta el camino y las tormentas son peligrosas.'
});
addLang('pt', {
  '<b>Walk</b>: tap a hex next to you, or any hex you have seen to travel there. Drag to look around; pinch, scroll or use the − and + buttons next to the menu to zoom (Settings: Map zoom).': '<b>Andar</b>: toca num hexágono ao lado para lá caminhar, ou em qualquer hexágono que já viste para viajar até lá. Arrasta para olhar em volta; belisca, desliza ou usa os botões − e + junto ao menu para ampliar o mapa (Definições: Zoom do mapa).',
  '<b>Bag and forge</b>: the Bag shows what you have equipped and what is spare. Keep the hides, fangs, ink essence and pearls you win: the blacksmith’s Forge turns them into stronger gear (+1 to +5) and into weapons and armour no shop sells. Every alchemist has a Brew tab: turn fish, hides, fangs and ink essence into potions.': '<b>Bolsa e forja</b>: a Bolsa mostra o que tens equipado e o que está a mais. Guarda as peles, presas, essências de tinta e pérolas que ganhares: a Forja do ferreiro transforma-as em equipamento mais forte (de +1 a +5) e em armas e armaduras que nenhuma loja vende. Cada alquimista tem um separador Preparar: transforma peixe, peles, presas e essência de tinta em poções.',
  '<b>Kingdom materials</b>: every kingdom has its own monster part (only its monsters drop it) and its own plant (when you stand where it grows, a <b>Gather</b> button appears; about 1 forest, plains or hills tile in 10). Its smiths and alchemists need them for that kingdom’s special gear and potion.': '<b>Materiais dos reinos</b>: cada reino tem uma parte de monstro (largada apenas pelos seus monstros) e uma planta próprias. Quando estás onde ela cresce, aparece o botão <b>Recolher</b>; encontra-se em cerca de 1 em cada 10 hexágonos de floresta, planície ou colina. Os ferreiros e alquimistas locais precisam destes materiais para o equipamento e a poção especiais do reino.',
  '<b>Fights</b>: you have 3 moves a turn. Your weapon gives your attacks; you can also block, change stance, drink a potion or use a technique.': '<b>Combates</b>: tens 3 ações por turno. A tua arma determina os ataques; também podes bloquear, mudar de postura, beber uma poção ou usar uma técnica.',
  '<b>The world</b>: eleven kingdoms on three continents, joined by narrow land bridges. Towns with a <b>Harbour</b> have ships to the other continents and to the Margin, the white island in the middle of the ocean.': '<b>O mundo</b>: onze reinos em três continentes, ligados por estreitas pontes de terra. As localidades com <b>porto</b> têm barcos para os outros continentes e para a Margem, a ilha branca no meio do oceano.',
  '<b>Survive</b>: eat as you travel (buy food or hunt), camp to heal, and watch the weather: snow slows you, fog hides the road, storms are dangerous.': '<b>Sobrevive</b>: come durante a viagem (compra comida ou caça), acampa para recuperar e tem atenção ao tempo: a neve abranda-te, o nevoeiro esconde o caminho e as tempestades são perigosas.'
});
addLang('ja', {
  '<b>Walk</b>: tap a hex next to you, or any hex you have seen to travel there. Drag to look around; pinch, scroll or use the − and + buttons next to the menu to zoom (Settings: Map zoom).': '<b>移動</b>：隣のマスをタップして歩くか、見たことのあるマスをタップしてそこまで旅しよう。ドラッグで見回し、ピンチやスクロール、メニュー横の−／＋ボタンでズームできる（設定：地図の拡大率）。',
  '<b>Bag and forge</b>: the Bag shows what you have equipped and what is spare. Keep the hides, fangs, ink essence and pearls you win: the blacksmith’s Forge turns them into stronger gear (+1 to +5) and into weapons and armour no shop sells. Every alchemist has a Brew tab: turn fish, hides, fangs and ink essence into potions.': '<b>かばんと鍛冶</b>：かばんには装備中の物と予備の物が表示される。手に入れた皮、牙、墨の精、真珠は取っておこう。鍛冶場では装備を強化（+1～+5）したり、店では買えない武器や防具を作ったりできる。錬金術師の「調合」タブでは、魚、皮、牙、墨の精から薬を作れる。',
  '<b>Kingdom materials</b>: every kingdom has its own monster part (only its monsters drop it) and its own plant (when you stand where it grows, a <b>Gather</b> button appears; about 1 forest, plains or hills tile in 10). Its smiths and alchemists need them for that kingdom’s special gear and potion.': '<b>王国の素材</b>：王国ごとに、その地の魔物だけが落とす素材と固有の植物がある。植物の生育場所に立つと<b>採集</b>ボタンが現れ、森・平原・丘の約10マスに1つ見つかる。鍛冶屋や錬金術師は、王国固有の装備や薬を作るためにこれらを必要とする。',
  '<b>Fights</b>: you have 3 moves a turn. Your weapon gives your attacks; you can also block, change stance, drink a potion or use a technique.': '<b>戦闘</b>：1ターンに3回行動できる。攻撃は武器で決まる。防御、構えの変更、薬を飲む、技を使うこともできる。',
  '<b>The world</b>: eleven kingdoms on three continents, joined by narrow land bridges. Towns with a <b>Harbour</b> have ships to the other continents and to the Margin, the white island in the middle of the ocean.': '<b>世界</b>：11の王国が3つの大陸に広がり、細い陸路でつながっている。<b>港</b>のある町からは、他の大陸や、海の中央に浮かぶ白い島「余白」へ船で渡れる。',
  '<b>Survive</b>: eat as you travel (buy food or hunt), camp to heal, and watch the weather: snow slows you, fog hides the road, storms are dangerous.': '<b>生き延びる</b>：旅の途中で食べ（食料を買うか狩る）、野営して回復しよう。天候にも注意。雪は歩みを遅くし、霧は道を隠し、嵐は危険だ。'
});
addLang('zh', {
  '<b>Walk</b>: tap a hex next to you, or any hex you have seen to travel there. Drag to look around; pinch, scroll or use the − and + buttons next to the menu to zoom (Settings: Map zoom).': '<b>移动</b>：点按相邻格子即可前往，或点按见过的格子沿路旅行。拖动环顾四周；双指捏合、滚动，或使用菜单旁的 − 和 + 按钮缩放地图（设置：地图缩放）。',
  '<b>Bag and forge</b>: the Bag shows what you have equipped and what is spare. Keep the hides, fangs, ink essence and pearls you win: the blacksmith’s Forge turns them into stronger gear (+1 to +5) and into weapons and armour no shop sells. Every alchemist has a Brew tab: turn fish, hides, fangs and ink essence into potions.': '<b>背包与锻造</b>：背包会显示已装备和备用的物品。留下获得的兽皮、獠牙、墨之精华和珍珠：铁匠的锻炉可用它们强化装备（+1 到 +5），也能打造商店买不到的武器和护甲。每位炼金术士都有「酿造」页签，可将鱼、兽皮、獠牙和墨之精华制成药水。',
  '<b>Kingdom materials</b>: every kingdom has its own monster part (only its monsters drop it) and its own plant (when you stand where it grows, a <b>Gather</b> button appears; about 1 forest, plains or hills tile in 10). Its smiths and alchemists need them for that kingdom’s special gear and potion.': '<b>王国材料</b>：每个王国都有专属怪物材料（只有当地怪物会掉落）和植物。站在植物生长处时会出现<b>采集</b>按钮；森林、平原或丘陵格子中约每10格有1格生长。当地铁匠和炼金术士需要这些材料制作王国专属装备和药水。',
  '<b>Fights</b>: you have 3 moves a turn. Your weapon gives your attacks; you can also block, change stance, drink a potion or use a technique.': '<b>战斗</b>：每回合有3次行动。武器决定你的攻击方式；你也可以格挡、切换架势、喝药或使用技艺。',
  '<b>The world</b>: eleven kingdoms on three continents, joined by narrow land bridges. Towns with a <b>Harbour</b> have ships to the other continents and to the Margin, the white island in the middle of the ocean.': '<b>世界</b>：十一个王国分布在三片大陆上，由狭窄的陆桥相连。拥有<b>港口</b>的城镇有船只通往其他大陆，也可前往海洋中央的白色岛屿「页边」。',
  '<b>Survive</b>: eat as you travel (buy food or hunt), camp to heal, and watch the weather: snow slows you, fog hides the road, storms are dangerous.': '<b>生存</b>：旅行时要进食（购买食物或狩猎），扎营恢复，并留意天气：降雪会减慢脚步，浓雾会遮住道路，暴风雨十分危险。'
});

addLang('fr', {
  '<b>Bag and forge</b>: the Bag shows what you have equipped and what is spare. Keep the hides, fangs, ink essence and pearls you win: the blacksmith’s Forge turns them into stronger gear (+# to +#) and into weapons and armour no shop sells. Every alchemist has a Brew tab: turn fish, hides, fangs and ink essence into potions.': '<b>Sac et forge</b> : le Sac montre ce que tu portes et ce qui est en réserve. Garde les peaux, crocs, essences d’encre et perles gagnés : la Forge du forgeron les transforme en équipement plus puissant (de +# à +#), ainsi qu’en armes et armures introuvables en boutique. Chaque alchimiste a un onglet Préparer : transforme poissons, peaux, crocs et essence d’encre en potions.',
  '<b>Kingdom materials</b>: every kingdom has its own monster part (only its monsters drop it) and its own plant (when you stand where it grows, a <b>Gather</b> button appears; about # forest, plains or hills tile in #). Its smiths and alchemists need them for that kingdom’s special gear and potion.': '<b>Matériaux des royaumes</b> : chaque royaume possède une partie de monstre (que seuls ses monstres lâchent) et une plante qui lui sont propres. Quand tu te tiens là où elle pousse, un bouton <b>Récolter</b> apparaît ; environ # case sur # en forêt, plaine ou colline en contient. Les forgerons et alchimistes du royaume en ont besoin pour son équipement et sa potion spéciale.',
  '<b>Fights</b>: you have # moves a turn. Your weapon gives your attacks; you can also block, change stance, drink a potion or use a technique.': '<b>Combats</b> : tu as # actions par tour. Ton arme détermine tes attaques ; tu peux aussi bloquer, changer de posture, boire une potion ou utiliser une technique.'
});
